@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:ital,wght@0,700;1,700&display=swap');

:root {
  color-scheme: light;
  font-family: 'DM Sans', sans-serif;
  color: #2d2627;
  background: #faf7f5;
  --wine: #672d3e;
  --wine-dark: #4b1d2b;
  --blush: #f1dcd8;
  --cream: #faf7f5;
  --ink: #2d2627;
  --muted: #766b6d;
  --line: #e8dedb;
  --surface: #fff;
  --soft: #f7f0ee;
  --shadow: 0 18px 48px rgb(75 29 43 / 8%);
}

* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body { margin: 0; min-width: 320px; min-height: 100vh; background: var(--cream); }
button, input, select, textarea { font: inherit; }
button:not(:disabled), a, summary { cursor: pointer; }
button:disabled { cursor: not-allowed; opacity: .56; box-shadow: none !important; }
a { color: var(--wine); text-decoration: none; }
img { max-width: 100%; }
app-icon { display: inline-flex; align-items: center; flex: 0 0 auto; }
.ui-icon { width: 20px; height: 20px; }
:focus-visible { outline: 3px solid #a46175; outline-offset: 3px; }

.app-header {
  height: 76px; padding: 0 clamp(1.25rem, 3vw, 3rem); display: flex; align-items: center;
  justify-content: space-between; gap: 1rem; border-bottom: 1px solid var(--line);
  background: rgb(255 255 255 / 94%); backdrop-filter: blur(14px);
  position: sticky; top: 0; z-index: 40;
}
.header-leading { display: flex; align-items: center; gap: .7rem; min-width: 0; }
.brand { font: 700 1.48rem 'Playfair Display', serif; color: var(--ink); white-space: nowrap; }
.brand em { color: var(--wine); }
.header-context { margin-left: auto; font-size: .81rem; color: var(--muted); font-weight: 700; }
.public-nav { display: flex; align-items: center; gap: 1rem; font-size: .9rem; font-weight: 700; }
.public-nav a:not(.nav-cta):hover { color: var(--wine-dark); text-decoration: underline; }
.nav-cta { color: white; background: var(--wine); padding: .72rem 1.15rem; border-radius: 999px; transition: .18s ease; }
.nav-cta:hover { color: white; background: var(--wine-dark); box-shadow: 0 8px 20px rgb(75 29 43 / 22%); }
.account-area { position: relative; }
.avatar-trigger {
  min-height: 48px; max-width: 240px; display: flex; align-items: center; gap: .65rem;
  padding: .32rem .55rem .32rem .35rem; border: 1px solid var(--line); border-radius: 999px;
  background: var(--surface); color: var(--ink); font-weight: 700; transition: .18s ease;
}
.avatar-trigger img { width: 36px; height: 36px; border-radius: 50%; object-fit: cover; }
.avatar-trigger .ui-icon { width: 15px; color: var(--muted); }
.account-name { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.avatar-trigger:hover, .avatar-trigger[aria-expanded="true"] {
  color: var(--wine); border-color: #cba6af; box-shadow: 0 7px 20px rgb(75 29 43 / 13%);
}
.account-menu {
  position: absolute; top: calc(100% + .55rem); right: 0; min-width: 205px;
  padding: .4rem; background: white; border: 1px solid var(--line); border-radius: 1rem;
  box-shadow: 0 18px 42px rgb(45 38 39 / 16%); z-index: 60;
}
.account-menu a, .account-menu button {
  width: 100%; min-height: 44px; display: flex; align-items: center; gap: .7rem;
  padding: .65rem .75rem; border: 0; border-radius: .65rem; background: transparent;
  color: var(--ink); text-align: left; font-weight: 600;
}
.account-menu a:hover, .account-menu button:hover:not(:disabled) {
  background: var(--soft); color: var(--wine); box-shadow: 0 4px 12px rgb(75 29 43 / 8%);
}
.menu-error { margin: .4rem .7rem; color: #8f2435; font-size: .8rem; }
.mobile-menu { display: none !important; }

.app-layout { display: grid; grid-template-columns: 258px minmax(0, 1fr); min-height: calc(100vh - 76px); }
.app-sidebar {
  padding: 1.55rem .95rem; border-right: 1px solid var(--line); background: #fffcfb;
  position: sticky; top: 76px; height: calc(100vh - 76px); display: flex; flex-direction: column;
}
.sidebar-intro { display: flex; align-items: center; gap: .75rem; padding: .15rem .75rem 1.6rem; }
.sidebar-intro strong, .sidebar-intro small { display: block; }
.sidebar-intro strong { font-size: .95rem; }
.sidebar-intro small { color: var(--muted); font-size: .77rem; margin-top: .15rem; }
.sidebar-monogram {
  width: 37px; height: 37px; display: grid; place-items: center; flex: 0 0 auto;
  border-radius: .75rem; background: var(--wine); color: white; font: 700 .92rem 'Playfair Display', serif;
}
