import { AuthService, Perfil } from './auth.service';
import { EstabelecimentoService } from './estabelecimento.service';
import { IconName, UiIconComponent } from './ui-icon.component';

interface NavItem {
  texto: string;
  icone: IconName;
  destino: string;
  fragmento?: string;
}

