  { path: 'unidades/:id/revisar', component: RevisaoAgendamentoComponent },
  { path: 'unidades/:id', component: FilialPublicaComponent },
  { path: '**', redirectTo: '' }
];

bootstrapApplication(AppComponent, {
  providers: [
