.directory-services { display: flex; flex-wrap: wrap; gap: .4rem; margin-top: 1.1rem; }
.directory-services span { max-width: 100%; padding: .35rem .65rem; border-radius: 99px; background: #f7f0ee; color: var(--wine-dark); font-size: .74rem; font-weight: 700; overflow-wrap: anywhere; }
.directory-price { margin: auto 0 .15rem; padding-top: 1.2rem; color: #453c3e; font-size: .88rem; font-weight: 700; }
.directory-card-link { display: inline-flex; align-items: center; gap: .4rem; min-height: 44px; margin-top: 1rem; color: var(--wine); font-weight: 700; }
.directory-card-link:hover { color: var(--wine-dark); text-decoration: underline; }
.directory-skeleton { min-height: 270px; border: 1px solid var(--line); border-radius: 1.3rem; background: linear-gradient(110deg, #f3eae7 20%, #fff 48%, #f3eae7 75%); }
.directory-empty { min-height: 290px; display: grid; justify-items: center; align-content: center; gap: .6rem; padding: 2rem; border: 1px dashed #d3b7b7; border-radius: 1.3rem; background: white; text-align: center; }
.directory-empty > app-icon { color: var(--wine); }
.directory-empty h2 { margin: .3rem 0 0; font: 700 1.8rem 'Playfair Display', serif; }
.directory-empty p { margin: 0 0 .5rem; color: #5e5052; }
.directory-pagination { display: flex; align-items: center; justify-content: center; gap: 1rem; flex-wrap: wrap; margin-top: 2rem; }
.directory-pagination span { color: #5e5052; font-size: .86rem; font-weight: 700; }
@media (max-width: 960px) {
  .directory-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (max-width: 700px) {
  .directory-search .button { width: 100%; }
}
@media (max-width: 580px) {
