    formatador = new Intl.DateTimeFormat('pt-BR', {
      day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit',
      timeZone: fusoHorario
    });
    formatadoresInstante.set(chave, formatador);
