  assert.deepEqual(dividirPeriodoAgenda('2026-10-06', '2026-10-06'), [
    { de: '2026-10-06', ate: '2026-10-06' }
  ]);
  assert.deepEqual(dividirPeriodoAgenda('2026-11-08', '2026-09-28'), []);
});

