FROM maven:3.9-eclipse-temurin-21

WORKDIR /workspace

COPY pom.xml ./
RUN mvn -q -DskipTests dependency:go-offline

COPY src ./src

EXPOSE 8080

CMD ["mvn", "spring-boot:run"]
name: estilo-marcado

services:
  postgres:
    image: postgres:17-alpine
    container_name: estilo-marcado-postgres
    environment:
      POSTGRES_DB: ${POSTGRES_DB}
      POSTGRES_USER: ${POSTGRES_USER}
      POSTGRES_PASSWORD: ${POSTGRES_PASSWORD}
    ports:
      - "${POSTGRES_PORT}:5432"
    volumes:
      - postgres_data:/var/lib/postgresql/data
    healthcheck:
      test: ["CMD-SHELL", "pg_isready -U $$POSTGRES_USER -d $$POSTGRES_DB"]
      interval: 5s
      timeout: 5s
      retries: 12
      start_period: 10s
    networks:
      - estilo_marcado_network

  backend:
    build:
      context: ./src/backend
      dockerfile: Dockerfile.dev
    container_name: estilo-marcado-backend
    environment:
      SPRING_PROFILES_ACTIVE: docker
      SPRING_DATASOURCE_URL: jdbc:postgresql://postgres:5432/${POSTGRES_DB}
      SPRING_DATASOURCE_USERNAME: ${POSTGRES_USER}
      SPRING_DATASOURCE_PASSWORD: ${POSTGRES_PASSWORD}
      MAIL_HOST: mailpit
      MAIL_PORT: 1025
      MAIL_FROM: ${MAIL_FROM:-nao-responda@estilomarcado.local}
      FRONTEND_URL: ${FRONTEND_URL:-http://localhost:4200}
      AUTH_ALLOWED_ORIGINS: ${AUTH_ALLOWED_ORIGINS:-http://localhost:4200}
      AUTH_PASSWORD_COST: ${AUTH_PASSWORD_COST:-12}
      FIREBASE_AUTH_ENABLED: ${FIREBASE_AUTH_ENABLED:-false}
      FIREBASE_AUTH_IMPORT_EXISTING: ${FIREBASE_AUTH_IMPORT_EXISTING:-false}
      FIREBASE_PROJECT_ID: ${FIREBASE_PROJECT_ID:-}
      FIREBASE_WEB_API_KEY: ${FIREBASE_WEB_API_KEY:-}
      FIREBASE_WEB_AUTH_DOMAIN: ${FIREBASE_WEB_AUTH_DOMAIN:-}
      FIREBASE_WEB_APP_ID: ${FIREBASE_WEB_APP_ID:-}
      FIREBASE_ADMIN_CREDENTIALS_PATH: ${FIREBASE_ADMIN_CREDENTIALS_PATH:-/run/firebase/service-account.json}
      FIREBASE_AUTH_EMULATOR_HOST: ${FIREBASE_AUTH_EMULATOR_HOST:-}
      FIREBASE_AUTH_EMULATOR_BROWSER_URL: ${FIREBASE_AUTH_EMULATOR_BROWSER_URL:-}
      SESSION_COOKIE_SECURE: ${SESSION_COOKIE_SECURE:-false}
      AUTH_BOOTSTRAP_ADMIN_ENABLED: ${AUTH_BOOTSTRAP_ADMIN_ENABLED:-false}
      AUTH_BOOTSTRAP_ADMIN_NAME: ${AUTH_BOOTSTRAP_ADMIN_NAME:-Administrador}
      AUTH_BOOTSTRAP_ADMIN_EMAIL: ${AUTH_BOOTSTRAP_ADMIN_EMAIL:-}
      AUTH_ADDITIONAL_ADMIN_EMAIL: ${AUTH_ADDITIONAL_ADMIN_EMAIL:-}
      AUTH_ADDITIONAL_ADMIN_NAME: ${AUTH_ADDITIONAL_ADMIN_NAME:-Administrador}
      AUTH_BOOTSTRAP_ADMIN_UNIT_ID: ${AUTH_BOOTSTRAP_ADMIN_UNIT_ID:-0}
      AUTH_BOOTSTRAP_ADMIN_UNIT_NAME: ${AUTH_BOOTSTRAP_ADMIN_UNIT_NAME:-Unidade Administrativa}
    command: mvn spring-boot:run -Dspring-boot.run.profiles=docker
    ports:
      - "${BACKEND_PORT}:8080"
    volumes:
      - ./src/backend:/workspace
      - ./deploy/firebase:/run/firebase:ro
      - maven_cache:/root/.m2
    depends_on:
      postgres:
        condition: service_healthy
      mailpit:
        condition: service_started
    networks:
      - estilo_marcado_network

  frontend:
    build:
      context: ./src/frontend
      dockerfile: Dockerfile.dev
    container_name: estilo-marcado-frontend
    # O volume de node_modules persiste entre rebuilds. Sincronize-o com o
    # package-lock atual antes de iniciar para evitar dependencias obsoletas.
    command: sh -c "npm install --no-audit --no-fund --prefer-offline && npm run start -- --host 0.0.0.0 --poll 1000"
    ports:
      - "${FRONTEND_PORT}:4200"
    volumes:
      - ./src/frontend:/workspace
      - frontend_node_modules:/workspace/node_modules
    depends_on:
      backend:
        condition: service_started
    networks:
      - estilo_marcado_network

  pgadmin:
    image: dpage/pgadmin4:latest
    container_name: estilo-marcado-pgadmin
    environment:
      PGADMIN_DEFAULT_EMAIL: ${PGADMIN_DEFAULT_EMAIL}
      PGADMIN_DEFAULT_PASSWORD: ${PGADMIN_DEFAULT_PASSWORD}
      PGADMIN_CONFIG_SERVER_MODE: "False"
    ports:
      - "${PGADMIN_PORT}:80"
    volumes:
      - pgadmin_data:/var/lib/pgadmin
    depends_on:
      postgres:
        condition: service_healthy
    networks:
      - estilo_marcado_network

  mailpit:
    image: axllent/mailpit:latest
    container_name: estilo-marcado-mailpit
    ports:
      - "${MAILPIT_SMTP_PORT}:1025"
      - "${MAILPIT_UI_PORT}:8025"
    networks:
      - estilo_marcado_network

volumes:
  postgres_data:
  pgadmin_data:
  maven_cache:
  frontend_node_modules:

networks:
  estilo_marcado_network:
    driver: bridge
package br.ufpa.dsai.estilomarcado.disponibilidade;

import static org.junit.jupiter.api.Assertions.assertEquals;

import java.time.Instant;
import java.time.LocalDate;
import java.time.LocalDateTime;
import java.time.LocalTime;
import java.time.ZoneId;
import java.util.List;

import org.junit.jupiter.api.Test;

import br.ufpa.dsai.estilomarcado.disponibilidade.service.CalculadoraHorarios;
import br.ufpa.dsai.estilomarcado.disponibilidade.service.CalculadoraHorarios.Ocupacao;
import br.ufpa.dsai.estilomarcado.disponibilidade.service.JanelaTrabalho;

class CalculadoraHorariosTest {
    private final CalculadoraHorarios calculadora = new CalculadoraHorarios();
    private final ZoneId fuso = ZoneId.of("America/Sao_Paulo");
    private final LocalDate data = LocalDate.of(2026, 10, 5);
    private final Instant antes = Instant.parse("2026-10-04T00:00:00Z");

    @Test
    void alinhaGradeERespeitaFimDaJanela() {
        var horarios = calcular(data, fuso, antes,
                List.of(new JanelaTrabalho(LocalTime.of(9, 7), LocalTime.of(10, 2))),
                List.of(), 30, 0);
        assertEquals(List.of(data.atTime(9, 15), data.atTime(9, 30)), horarios);
    }

    @Test
    void naoUneJanelasAdjacentesNemAtravessaMeiaNoite() {
        assertEquals(List.of(), calcular(data, fuso, antes,
                List.of(new JanelaTrabalho(LocalTime.of(9, 0), LocalTime.of(9, 30)),
                        new JanelaTrabalho(LocalTime.of(9, 30), LocalTime.of(10, 0))),
                List.of(), 45, 0));
        assertEquals(List.of(), calcular(data, fuso, antes,
                List.of(new JanelaTrabalho(LocalTime.of(23, 30), LocalTime.of(23, 59))),
                List.of(), 45, 0));
    }

    @Test
    void aplicaPausaExistenteEPausaDoCandidato() {
        var ocupacoes = List.of(new Ocupacao(data.atTime(9, 0), 45, 15),
                new Ocupacao(data.atTime(11, 0), 30, 0));
        var horarios = calcular(data, fuso, antes,
                List.of(new JanelaTrabalho(LocalTime.of(9, 0), LocalTime.NOON)),
                ocupacoes, 45, 15);
        assertEquals(List.of(data.atTime(10, 0)), horarios);
    }

    @Test
    void permiteUltimoServicoMesmoComPausaForaDaJornada() {
        assertEquals(List.of(data.atTime(11, 15)), calcular(data, fuso, antes,
                List.of(new JanelaTrabalho(LocalTime.of(11, 15), LocalTime.NOON)),
                List.of(), 45, 30));
    }

    @Test
    void comparaPeriodosOcupadosSemiabertosComIntervalosDosDoisLados() {
        List<JanelaTrabalho> janela = List.of(new JanelaTrabalho(LocalTime.of(9, 0), LocalTime.NOON));
        assertEquals(List.of(data.atTime(10, 0), data.atTime(10, 15), data.atTime(10, 30),
                        data.atTime(10, 45), data.atTime(11, 0), data.atTime(11, 15), data.atTime(11, 30)),
                calcular(data, fuso, antes, janela,
                        List.of(new Ocupacao(data.atTime(9, 0), 30, 30)), 30, 0));
        assertEquals(List.of(data.atTime(9, 0), data.atTime(9, 15), data.atTime(9, 30),
                        data.atTime(9, 45), data.atTime(10, 0), data.atTime(10, 15),
                        data.atTime(11, 30)),
                calcular(data, fuso, antes, janela,
                        List.of(new Ocupacao(data.atTime(11, 0), 30, 0)), 30, 15));
    }

    @Test
    void excluiInicioPassadoPeloRelogioDaFilial() {
        assertEquals(List.of(data.atTime(10, 15)), calcular(data, fuso,
                data.atTime(10, 1).atZone(fuso).toInstant(),
                List.of(new JanelaTrabalho(LocalTime.of(10, 0), LocalTime.of(10, 45))),
                List.of(), 30, 0));
    }

    @Test
    void excluiHorasInexistentesEAmbiguasEmTransicoesDeFuso() {
        ZoneId novaYork = ZoneId.of("America/New_York");
        LocalDate primavera = LocalDate.of(2026, 3, 8);
        assertEquals(List.of(), calcular(primavera, novaYork, antes,
                List.of(new JanelaTrabalho(LocalTime.of(1, 30), LocalTime.of(3, 30))),
                List.of(), 60, 0));
        LocalDate outono = LocalDate.of(2026, 11, 1);
        assertEquals(List.of(), calcular(outono, novaYork, antes,
                List.of(new JanelaTrabalho(LocalTime.of(1, 0), LocalTime.of(2, 0))),
                List.of(), 30, 0));
    }

    private List<LocalDateTime> calcular(LocalDate data, ZoneId zona, Instant agora,
            List<JanelaTrabalho> janelas, List<Ocupacao> ocupacoes, int duracao, int intervalo) {
        return calculadora.calcular(data, zona, agora, janelas, ocupacoes, duracao, intervalo);
    }
}

